INSERT INTO kv (k, v, updated_at) VALUES ('park/score/notice', '[{"id":1,"appType":"smart_city","cover":"img/news3.jpg","title":"我市智慧交通系统全面升级，主干道通行效率提升 23%","subTitle":"智慧城市 · 数字化治理系列报道","content":"<p><strong>我市智慧交通系统全面升级，主干道通行效率提升 23%</strong></p><p>近日，记者从市智慧城市建设领导小组办公室获悉，围绕“一网通办、一网统管、一屏通览”的总体目标，我市持续深化数据要素市场化配置改革，推动城市治理数字化转型取得阶段性成效。</p><p>据介绍，本期建设重点覆盖交通出行、政务服务、医疗健康、社区治理四大领域。通过统一数据底座和标准化接口，各部门业务系统实现互联互通，跨部门协同处置效率明显提升。</p><p>下一步，我市将扩大试点范围，完善数据安全与隐私保护机制，让市民在更多场景中感受到数字化带来的便利。</p><p>（来源：市智慧城市建设领导小组办公室）</p>","status":"Y","publishDate":"2026-10-21","tags":null,"commentNum":10,"likeNum":25,"readNum":357,"type":"16","top":"Y","hot":"N","typeName":"今日要闻"},{"id":2,"appType":"smart_city","cover":"img/news1.jpg","title":"数字政务“一网通办”新增 48 项高频事项，覆盖率达 96%","subTitle":"智慧城市 · 数字化治理系列报道","content":"<p><strong>数字政务“一网通办”新增 48 项高频事项，覆盖率达 96%</strong></p><p>近日，记者从市智慧城市建设领导小组办公室获悉，围绕“一网通办、一网统管、一屏通览”的总体目标，我市持续深化数据要素市场化配置改革，推动城市治理数字化转型取得阶段性成效。</p><p>据介绍，本期建设重点覆盖交通出行、政务服务、医疗健康、社区治理四大领域。通过统一数据底座和标准化接口，各部门业务系统实现互联互通，跨部门协同处置效率明显提升。</p><p>下一步，我市将扩大试点范围，完善数据安全与隐私保护机制，让市民在更多场景中感受到数字化带来的便利。</p><p>（来源：市智慧城市建设领导小组办公室）</p>","status":"Y","publishDate":"2026-10-20","tags":null,"commentNum":17,"likeNum":38,"readNum":514,"type":"17","top":"Y","hot":"N","typeName":"本地资讯"},{"id":3,"appType":"smart_city","cover":"img/news2.jpg","title":"城市大脑上线运行一周年，累计处置城市事件 12.6 万件","subTitle":"智慧城市 · 数字化治理系列报道","content":"<p><strong>城市大脑上线运行一周年，累计处置城市事件 12.6 万件</strong></p><p>近日，记者从市智慧城市建设领导小组办公室获悉，围绕“一网通办、一网统管、一屏通览”的总体目标，我市持续深化数据要素市场化配置改革，推动城市治理数字化转型取得阶段性成效。</p><p>据介绍，本期建设重点覆盖交通出行、政务服务、医疗健康、社区治理四大领域。通过统一数据底座和标准化接口，各部门业务系统实现互联互通，跨部门协同处置效率明显提升。</p><p>下一步，我市将扩大试点范围，完善数据安全与隐私保护机制，让市民在更多场景中感受到数字化带来的便利。</p><p>（来源：市智慧城市建设领导小组办公室）</p>","status":"Y","publishDate":"2026-10-19","tags":null,"commentNum":24,"likeNum":51,"readNum":671,"type":"18","top":"Y","hot":"Y","typeName":"政策解读"},{"id":4,"appType":"smart_city","cover":"img/news3.jpg","title":"全市新增 3200 个公共停车泊位，重点缓解老城区停车难","subTitle":"智慧城市 · 数字化治理系列报道","content":"<p><strong>全市新增 3200 个公共停车泊位，重点缓解老城区停车难</strong></p><p>近日，记者从市智慧城市建设领导小组办公室获悉，围绕“一网通办、一网统管、一屏通览”的总体目标，我市持续深化数据要素市场化配置改革，推动城市治理数字化转型取得阶段性成效。</p><p>据介绍，本期建设重点覆盖交通出行、政务服务、医疗健康、社区治理四大领域。通过统一数据底座和标准化接口，各部门业务系统实现互联互通，跨部门协同处置效率明显提升。</p><p>下一步，我市将扩大试点范围，完善数据安全与隐私保护机制，让市民在更多场景中感受到数字化带来的便利。</p><p>（来源：市智慧城市建设领导小组办公室）</p>","status":"Y","publishDate":"2026-10-18","tags":null,"commentNum":31,"likeNum":64,"readNum":828,"type":"19","top":"N","hot":"N","typeName":"民生关注"}]', datetime('now'));
