INSERT INTO kv (k, v, updated_at) VALUES ('traffic/checkCar', '{"id":1,"title":"机动车安全技术检验须知","notice":"<p><strong>一、检验周期</strong></p><p>非营运小型客车 6 年内每 2 年检验一次，超过 6 年每年检验一次，超过 15 年每半年检验一次。</p><p><strong>二、所需材料</strong></p><p>机动车行驶证原件、交强险凭证、车主身份证原件。</p><p><strong>三、注意事项</strong></p><p>请提前处理完毕交通违法记录，保持车辆外观与登记信息一致，随车携带三角警示牌。</p>","createTime":"2026-01-05 09:00:00","updateTime":"2026-09-01 10:20:00"}', datetime('now'));
